Object.assign(words.ar,{heroTitle:'للوقت مقام.<br><em>وللذوق بصمة.</em>',heroDescription:'يا مرحبا بأهل الذوق. مجلسٌ يجمع جمال الصنعة وندرة التفاصيل، في مجموعة ساعات صاحب السمو الشيخ عمار بن حميد النعيمي.',museumLabel:'مجلس الوقت · متحف الشيخ عمار',enter:'اكتشف المجموعة',tour:'جولة المتحف',tourStart:'ابدأ الجولة المختارة',tourTitle:'قطعة. ولحظة تأمّل.',tourIntro:'ثلاث محطات من المجموعة، من شخصية المينا إلى جرأة الحركة. تنقّل على مهلك، وافتح تفاصيل القطعة متى شئت.',tourRoom:'جولة مختارة',tourNext:'المحطة التالية',tourPrev:'المحطة السابقة',tourPlay:'تشغيل الجولة',tourPause:'إيقاف الجولة',tourAll:'شاهد الساعات الـ42',tourDetail:'تأمّل التفاصيل',tourPosition:'المحطة',ajmanTime:'الوقت في عجمان',pieces:'قطعة في المجموعة',maisons:'دور للساعات',languages:'لغتان للزيارة',featuredTitle:'ثلاث نوافذ على الاستثناء',featuredIntro:'أثر التاريخ. خيال الحركة. وجرأة المواد. بداية مختارة لزيارة لا تستعجل الوقت.',filmTitle:'داخل عالم الساعات',filmIntro:'لقاءٌ بالصنعة والذوق. شاهد المجموعة، ثم عد إلى تفاصيلها.',chapterOne:'أثر التاريخ',chapterTwo:'خيال الحركة',chapterThree:'جرأة المواد',chapterOneText:'مينا يحمل شخصية لا تخطئها العين. تأمّل حضور الصقر، ثم اكتشف تفاصيل كرونوغراف دايتونا.',chapterTwoText:'قراءةٌ للساعة بإشارة يد. هنا تتحول الآلية الدقيقة إلى لغة بصرية، تفتح سؤالاً جديداً عن شكل الوقت.',chapterThreeText:'هندسة تظهر للعين. طبقات الحركة وألوانها تمنح الكرونوغراف حضوراً معاصراً واضح الشخصية.'});
Object.assign(words.en,{heroTitle:'Time has a place.<br><em>Taste leaves a mark.</em>',heroDescription:'Welcome to the Majlis of Time. A considered encounter with watchmaking, through the collection of His Highness Sheikh Ammar bin Humaid Al Nuaimi.',museumLabel:'Majlis of Time · Sheikh Ammar Museum',enter:'Discover the collection',tour:'Museum tour',tourStart:'Begin the selected tour',tourTitle:'One piece. A moment to look.',tourIntro:'Three encounters, from the character of a dial to the imagination of a movement. Move at your own pace and open each timepiece for a closer look.',tourRoom:'A selected journey',tourNext:'Next encounter',tourPrev:'Previous encounter',tourPlay:'Play the tour',tourPause:'Pause the tour',tourAll:'Explore all 42 timepieces',tourDetail:'Look closer',tourPosition:'Encounter',ajmanTime:'Time in Ajman',pieces:'timepieces',maisons:'watchmaking houses',languages:'languages',featuredTitle:'Three windows into the exceptional',featuredIntro:'The imprint of history. Mechanical imagination. Material expression. A considered beginning to an unhurried visit.',filmTitle:'Inside watchmaking',filmIntro:'An encounter with craft and taste. Watch the collection, then return to its details.',chapterOne:'The imprint of history',chapterTwo:'Mechanical imagination',chapterThree:'Material expression',chapterOneText:'A dial with an unmistakable character. Consider the presence of the falcon, then explore the details of this Daytona chronograph.',chapterTwoText:'Time indicated by the gesture of a hand. A precise mechanism becomes a visual language, asking us to see the hour differently.',chapterThreeText:'Engineering made visible. Layers of mechanics and colour give this chronograph an unmistakably contemporary presence.'});
const tourSlugs=['rolex-daytona-6263-quraysh-hawk','fp-journe-ffc-francis-ford-coppola-calibre-13003','richard-mille-rm-65-01-automatic-split-seconds-chronograph-mclaren-w1'];
featuredItems=()=>tourSlugs.map(slug=>state.all.find(w=>w.slug===slug)).filter(Boolean);
let tourIndex=0,tourPlaying=false;
function tourItems(){return featuredItems()}
function renderTour(){const host=$('#exhibition');if(!host||!state.all.length)return;const items=tourItems();if(!items.length)return;const slug=decodeURIComponent(location.hash.slice(1));const found=items.findIndex(w=>w.slug===slug);if(found>=0)tourIndex=found;tourIndex=Math.min(tourIndex,items.length-1);const w=items[tourIndex];
 $('#tourImage').src=imageFor(w);$('#tourImage').alt=local(w,'name');$('#tourBrand').textContent=w.brand;$('#tourName').textContent=local(w,'name');$('#tourRef').textContent=w.referenceNumber||'';$('#tourChapter').textContent=t(['chapterOne','chapterTwo','chapterThree'][tourIndex]);$('#tourText').textContent=t(['chapterOneText','chapterTwoText','chapterThreeText'][tourIndex]);$('#tourCount').textContent=(tourIndex+1)+' / '+items.length;
 $('#tourPrev').disabled=tourIndex===0;$('#tourNext').disabled=tourIndex===items.length-1;$('#tourPlay').textContent=t(tourPlaying?'tourPause':'tourPlay');$('#tourPlay').setAttribute('aria-pressed',String(tourPlaying));
 $$('#tourDots button').forEach((b,i)=>{b.setAttribute('aria-pressed',String(i===tourIndex));b.setAttribute('aria-label',local(items[i],'name'));b.querySelector('span').textContent=t(['chapterOne','chapterTwo','chapterThree'][i])});
 $('#tourDetail').onclick=()=>openDetail(w);
}
function tourGo(n,manual=true){if(manual)tourPlaying=false;tourIndex=Math.max(0,Math.min(tourItems().length-1,n));const w=tourItems()[tourIndex];if(!w)return;history.pushState(null,'','#'+encodeURIComponent(w.slug));renderTour()}
$('#tourPrev')?.addEventListener('click',()=>tourGo(tourIndex-1));$('#tourNext')?.addEventListener('click',()=>tourGo(tourIndex+1));
$('#tourPlay')?.addEventListener('click',()=>{tourPlaying=!tourPlaying;if(tourIndex===tourItems().length-1&&tourPlaying)tourGo(0,false);renderTour()});
$$('#tourDots button').forEach((b,i)=>b.addEventListener('click',()=>tourGo(i)));
window.addEventListener('popstate',()=>{tourPlaying=false;tourIndex=0;renderTour()});
document.addEventListener('keydown',e=>{if(document.body.dataset.page!=='exhibition'||$('#detail').open||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();tourGo(tourIndex+(e.key==='ArrowRight'?1:-1)*(state.ar?-1:1))}});
setInterval(()=>{if(document.body.dataset.page!=='exhibition'||!tourPlaying||document.hidden||$('#detail').open||document.activeElement===$('#tourDetail'))return;if(tourIndex>=tourItems().length-1){tourPlaying=false;renderTour()}else tourGo(tourIndex+1,false)},9000);
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',e=>{if(e.matches){tourPlaying=false;renderTour()}});
function tickAjman(){const clock=$('#ajmanClock');if(clock)clock.textContent=new Intl.DateTimeFormat(state.ar?'ar-AE':'en-GB',{timeZone:'Asia/Dubai',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date())}
const classicTranslate=translate;translate=()=>{classicTranslate();renderTour();tickAjman();if(document.body.dataset.page==='exhibition')document.title=t('tour')+' | '+t('museumLabel')};setInterval(tickAjman,60000);translate();
